const USER_INPUT_ALLOWED_DIRS = [
    "app",
    "pages",
    "public",
    "components",
    "lib",
    "src",
    "utils",
    "helpers",
    "hooks",
    "services",
    "styles",
    "assets",
    "constants",
    "types",
    "api",
];
function createPreset(baseDir, options) {
    return {
        baseDir,
        ...options,
    };
}
const INTERNAL_PRESET = {
    level: "normal",
    followSymlinks: false,
    checkExists: false,
    allowAbsolute: false,
};
const BUILD_PRESET = {
    level: "normal",
    followSymlinks: true,
    checkExists: false,
    allowAbsolute: true,
};
export const ValidationPresets = {
    userInput(baseDir) {
        return createPreset(baseDir, {
            level: "strict",
            allowedDirs: [...USER_INPUT_ALLOWED_DIRS],
            followSymlinks: false,
            checkExists: true,
            allowAbsolute: false,
        });
    },
    internal(baseDir) {
        return createPreset(baseDir, INTERNAL_PRESET);
    },
    build(baseDir) {
        return createPreset(baseDir, BUILD_PRESET);
    },
    static(baseDir) {
        return createPreset(baseDir, {
            level: "normal",
            allowedDirs: ["dist", "public"],
            followSymlinks: false,
            checkExists: true,
            allowAbsolute: false,
        });
    },
};
